DECLARE packs jsonb := $pack$[{"codigo":"S22D-C01","legacy_id":501,"legacy_ids":[501,503],"relacionadas":["S7-C10","S5-C17","S7-C06"],"residual":"","coberturas":[{"legacy_id":501,"estado_cobertura":"REEMPLAZADA","residual":"","diferencias":"En solicitud inicial o reenvío OTP B2B de PASSWORD_RECOVERY o AUTH_NEW_DEVICE_OTP_SEND BLOQUEAR consumir o bloquear contadores de otra operación OTP o correo transaccional. La IP es señal preventiva de riesgo, no causa autónoma de bloqueo en estas operaciones. En recuperación, derivar sujeto mediante HMAC del correo canónico server-side con secreto runtime y consumir contador independientemente de existencia de cuenta. Para segundo control, conservar reenvío del mismo OTP vigente con intentos disponibles conforme S7-C06; nueva emisión solo conforme política de su operación. Complementa S7-C10 y S5-C17; no modifica cuotas, ventanas ni políticas existentes. Binding pendiente."},{"legacy_id":503,"estado_cobertura":"REEMPLAZADA","residual":"","diferencias":"En solicitud inicial o reenvío OTP B2B de PASSWORD_RECOVERY o AUTH_NEW_DEVICE_OTP_SEND BLOQUEAR consumir o bloquear contadores de otra operación OTP o correo transaccional. La IP es señal preventiva de riesgo, no causa autónoma de bloqueo en estas operaciones. En recuperación, derivar sujeto mediante HMAC del correo canónico server-side con secreto runtime y consumir contador independientemente de existencia de cuenta. Para segundo control, conservar reenvío del mismo OTP vigente con intentos disponibles conforme S7-C06; nueva emisión solo conforme política de su operación. Complementa S7-C10 y S5-C17; no modifica cuotas, ventanas ni políticas existentes. Binding pendiente."}],"hechos":["s22d01_operacion_otp_b2b","s22d01_contador_cruzado","s22d01_bloqueo_solo_ip","s22d01_recuperacion","s22d01_sujeto_hmac_invalido","s22d01_consumo_depende_existencia","s22d01_segundo_control","s22d01_reenvio_o_emision_invalido"],"paquete":{"tipo":"NUEVA","codigo":"S22D-C01","clave":"s22d_legacy_501"