invalido":false,"s22d01_consumo_depende_existencia":false,"s22d01_segundo_control":true,"s22d01_reenvio_o_emision_invalido":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s22d01_operacion_otp_b2b":false,"s22d01_contador_cruzado":true,"s22d01_bloqueo_solo_ip":true,"s22d01_recuperacion":true,"s22d01_sujeto_hmac_invalido":true,"s22d01_consumo_depende_existencia":true,"s22d01_segundo_control":true,"s22d01_reenvio_o_emision_invalido":true},"esperado":false}]},"hash":"8e243d7a50740836abc41f736d62bcce26fbe7723392c03d5579924212de2f3e","hash_paquete":"0385f97967c884c7c4ffce038d17ccc84f3a3cb526677f6f71d60f793befbcfd","hash_evaluado":"8e243d7a50","hash_paquete_10":"0385f97967"},{"codigo":"S22D-C02","legacy_id":625,"legacy_ids":[625],"relacionadas":[],"residual":"","coberturas":[{"legacy_id":625,"estado_cobertura":"REEMPLAZADA","residual":"","diferencias":"En devolución de pago confirmado BLOQUEAR sustituir retorno de dinero por billetera, saldo, crédito interno LF, bono o cupón obligatorio. Preferir ruta original cuando proveedor la soporte y exista reconciliación autoritativa. Beneficio comercial adicional se registra y presenta separado de devolución. Frontend no decide elegibilidad, monto, destino ni estado. Binding pendiente."}],"hechos":["s22d02_devolucion_pago_confirmado","s22d02_sustitucion_no_monetaria","s22d02_ruta_original_viable_reconciliada","s22d02_ruta_original_omitida_sin_justificacion","s22d02_beneficio_no_separado","s22d02_frontend_decide"],"paquete":{"tipo":"NUEVA","codigo":"S22D-C02","clave":"s22d_legacy_625","familia":"PAYMENTS_CHECKOUT","naturaleza":"CONDUCTA","clase":"PANTALLA","alcance":"CLIENT_PAYMENTS","modo":"HEREDA","dueno":"PRODUCTO","titulo":"Devolución monetaria sin saldo interno LF","descripcion":"En devolución de pago confirmado BLOQUEAR sustituir retorno de dinero por billetera, saldo, crédito interno LF, bono o cupón obligatorio. Preferir ruta original cuando proveedor la soporte y exista reconciliación autoritativa. Beneficio comercial adicional se registra y presenta separado de devolución. Frontend no decide elegibilidad, monto, destino ni estado. Binding pendiente.","efecto":"BLOQUEAR","autoridad":"LEG-PRODUCTO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/625","solicitante":"Cristhian / Claude S22-D 2026-11-24"},"condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"s22d02_devolucion_pago_confirmado"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"=","izq":{"hecho":"s22d02_sustitucion_no_monetaria"},"der":{"lit":true}},"der":{"op":"y","izq":{"op":"=","izq":{"hecho":"s22d02_ruta_original_viable_reconciliada"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"s22d02_ruta_original_omitida_sin_justificacion"},"der":{"lit":true}}}},"der":{"op":"=","izq":{"hecho":"s22d02_beneficio_no_separado"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s22d02_frontend_decide"},"der":{"lit":true}}}},"pruebas":[{"casuistica":"NO_SE_CUMPLE","entrada":{"s22d02_devolucion_pago_confirmado":true,"s22d02_sustitucion_no_monetaria":false,"s22d02_ruta_original_viable_reconciliada":true,"s22d02_ruta_original_omitida_sin_justificacion":false,"s22d02_beneficio_no_separado":false,"s22d02_frontend_decide":false},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"s22d02_devolucion_pago_confirmado":true,"s22d02_sustitucion_no_monetaria":true,"s22d02_ruta_original_viable_reconciliada":true,"s22d02_ruta_original_omitida_sin_justificacion":false,"s22d02_beneficio_no_separado":false,"s22d02_frontend_decide":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22d02_devolucion_pago_confirmado":true,"s22d02_sustitucion_no_monetaria":false,"s22d02_ruta_original_viable_reconciliada":true,"s22d02_ruta_original_omitida_sin_justificacion":true,"s22d02_beneficio_no_separado":false,"s22d02_frontend_decide":false},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"s22d02_devolucion_pago_confirmado":true,"s22d02_sustitucion_no_monetaria":false,"s22d02_ruta_original_viable_reconciliada":false,"s22d02_ruta_original_omitida_sin_justificacion":true,"s22d02_beneficio_no_separado":false,"s22d02_frontend_decide":false},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"s22d02_devolucion_pago_confirmado":true,"s22d02_sustitucion_no_monetaria":false,"s22d02_ruta_original_viable_reconciliada":false,"s22d02_ruta_original_omitida_sin_justificacion":false,"s22d02_beneficio_no_separado":true,"s22d02_frontend_decide":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22d02_devolucion_pago_confirmado":true,"s22d02_sustitucion_no_monetaria":false,"s22d02_ruta_original_viable_reconciliada":false,"s22d02_ruta_original_omitida_sin_justificacion":false,"s22d02_beneficio_no_separado":false,"s22d02_frontend_decide":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"s22d02_devolucion_pago_confirmado":false,"s22d02_sustitucion_no_monetaria":true,"s22d02_ruta_original_viable_reconciliada":true,"s22d02_ruta_original_omitida_sin_justificacion":true,"s22d02_beneficio_no_separado":true,"s22d02_frontend_decide":true},"esperado":false}]},"hash":"67c6d6618a790d8364bae4119f764d1f8f220128bef667431c80564b5c5bc848","hash_paquete":"09182b1e7dcbacd839b26e5f1d58e5e68945f83d404d2bb8554fddb6983b8197","hash_evaluado":"67c6d6618a","hash_paquete_10":"09182b1e7d"}]$pack$::jsonb; p jsonb; a jsonb; ans jsonb; cd text; h text; t record; n int:=0; vectors int:=0; b_leg jsonb; b_dep jsonb; b_cfg jsonb; val jsonb; lid int; residual text; diff text; old_desc text; new_desc text; links int:=0; before_replaced int; after_replaced int; direct_hash text; c jsonb;
BEGIN
 SELECT count(DISTINCT legacy_id) INTO before_replaced FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA';
 SELECT jsonb_agg(to_jsonb(x) ORDER BY id) INTO b_leg FROM lf_ops.reglas x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) INTO b_dep FROM lf_ops.nucleo_deprecaciones x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) INTO b_cfg FROM public.lf_global_config x;
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 a:=p->'paquete'; cd:=p->>'codigo';
 IF EXISTS(WITH RECURSIVE anc AS (SELECT codigo,padre FROM lf_ops.nucleo_nodos WHERE pantalla_id=36 UNION ALL SELECT nn.codigo,nn.padre FROM lf_ops.nucleo_nodos nn JOIN anc z ON nn.codigo=z.padre) SELECT 1 FROM anc WHERE codigo=a->>'alcance') THEN RAISE EXCEPTION 'S22_SCOPE_P36 %',cd; END IF;
 ans:=lf_ops.nucleo_regla_proponer_v1(a,true);
 IF ans->>'resultado' IS DISTINCT FROM 'CANDIDATA' OR (ans->>'version')::int IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'S22_PROPOSAL_FAIL % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true); h:=lf_ops.nucleo_hash_paquete_v1(cd,1);
 IF h IS DISTINCT FROM p->>'hash_paquete' OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1 AND estado='CANDIDATA' AND hash=p->>'hash') THEN RAISE EXCEPTION 'S22_ATTESTATION_DRIFT %',cd; END IF;
 FOR t IN SELECT entrada,esperado FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1 LOOP
 IF lf_ops.nucleo_eval_v1(a->'condicion',t.entrada) IS DISTINCT FROM t.esperado THEN RAISE EXCEPTION 'S22_VECTOR_FAIL %',cd; END IF; vectors:=vectors+1; END LOOP;
 n:=n+1;
 END LOOP;
 IF n<>2 OR vectors<>15 THEN RAISE EXCEPTION 'S22_VECTOR_COUNT'; END IF;
 IF (SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM lf_ops.reglas x) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones x) IS DISTINCT FROM b_dep OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) FROM public.lf_global_config x) IS DISTINCT FROM b_cfg THEN RAISE EXCEPTION 'S22_INVARIANT_FAIL'; END IF;
 IF jsonb_array_length(lf_ops.lf_nucleo_lectura_transicion_v1(36,'INPUT_GOVERNANCE','DIRECTAS')->'nativas') IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'S22_DPIG03_FAIL'; END IF;
 RAISE NOTICE 'S22D proposal-only: independent judgment pending';
END $s22$;
COMMIT;
